<?php

namespace App\Filament\Support;

use Filament\Forms\Components\FileUpload;
use Filament\Forms\Components\Textarea;
use Filament\Forms\Components\TextInput;
use Filament\Schemas\Components\Section;

/**
 * The per-record SEO block, identical on pages, posts and courses.
 *
 * Legacy Joomla had `metadesc` empty on all 29 articles, so these were
 * generated by `ai:generate-seo` and flagged with `ai_meta_generated` for a
 * human to review.
 */
class SeoFields
{
    public static function section(): Section
    {
        return Section::make('SEO & sharing')
            ->description('Controls how this page appears in Google and when shared on social media.')
            ->collapsed()
            ->schema([
                TextInput::make('meta_title')
                    ->label('Meta title')
                    ->maxLength(255)
                    ->helperText('Leave blank to use the page title.'),

                Textarea::make('meta_description')
                    ->label('Meta description')
                    ->rows(3)
                    ->maxLength(320)
                    ->helperText('Aim for 140–160 characters.'),

                FileUpload::make('og_image')
                    ->label('Share image')
                    ->image()
                    ->disk('public')
                    ->directory('media/og')
                    ->imageEditor()
                    ->helperText('Shown when the page is shared. Falls back to the featured image.'),
            ])
            ->columns(1);
    }
}
